[{"name_path": "ConfigSchema", "kind": "Constant", "relative_path": "src/config.ts", "body_location": {"start_line": 130, "end_line": 153}, "body": "export const ConfigSchema = BaseConfigSchema.superRefine((cfg, ctx) => {
  const seatKeys: Seat[] = ['pm', 'dev', 'qc'];
  if (cfg.seats.audit) {
    seatKeys.push('audit');
  }
  for (const seat of seatKeys) {
    const agentId = cfg.seats[seat];
    if (!agentId) continue;
    const agent = Object.hasOwn(cfg.agents, agentId) ? cfg.agents[agentId] : undefined;
    if (!agent) {
      ctx.addIssue({
        code: 'custom',
        message: `Seat '${seat}' points to unknown agent '${agentId}'`,
        path: ['seats', seat],
      });
    } else if (!agent.can_sit.includes(seat)) {
      ctx.addIssue({
        code: 'custom',
        message: `Agent '${agentId}' cannot sit in seat '${seat}' (can_sit: ${agent.can_sit.join(', ')})`,
        path: ['seats', seat],
      });
    }
  }
});"}]

